// TreeNode is provided by the starter (Models.cs): int Value; TreeNode Left, Right.

// LeetCode 272 — the k values in a BST closest to a target, ascending. On a distance tie the smaller value wins.
// Follow-up asked at LinkedIn: better than O(n). Two stacks walk outward from the target: O(h + k) per query.
public static class ClosestBstK {
    public static IList<int> KClosest(TreeNode root, double target, int k) {
        // pred: the path to values <= target (top = the largest such value)
        // succ: the path to values >  target (top = the smallest such value)
        var pred = new Stack<TreeNode>();
        var succ = new Stack<TreeNode>();
        TreeNode cur = root;
        while (cur != null) {                       // one root-to-leaf walk fills both stacks: O(h)
            if (cur.Value <= target) { pred.Push(cur); cur = cur.Right; }
            else { succ.Push(cur); cur = cur.Left; }
        }
        var smaller = new List<int>();              // collected in descending order
        var larger = new List<int>();               // collected in ascending order
        while (smaller.Count + larger.Count < k && (pred.Count > 0 || succ.Count > 0)) {
            bool takeSmaller;
            if (pred.Count == 0) takeSmaller = false;
            else if (succ.Count == 0) takeSmaller = true;
            else takeSmaller = target - pred.Peek().Value <= succ.Peek().Value - target;   // tie → the smaller value
            if (takeSmaller) smaller.Add(NextSmaller(pred));
            else larger.Add(NextLarger(succ));
        }
        var result = new List<int>(smaller.Count + larger.Count);
        for (int i = smaller.Count - 1; i >= 0; i--) result.Add(smaller[i]);   // ascending order
        result.AddRange(larger);
        return result;
    }

    // Pop the largest value <= target, then line up the next one: the largest value in its left subtree.
    private static int NextSmaller(Stack<TreeNode> pred) {
        TreeNode node = pred.Pop();
        for (TreeNode c = node.Left; c != null; c = c.Right) pred.Push(c);
        return node.Value;
    }

    // Pop the smallest value > target, then line up the next one: the smallest value in its right subtree.
    private static int NextLarger(Stack<TreeNode> succ) {
        TreeNode node = succ.Pop();
        for (TreeNode c = node.Right; c != null; c = c.Left) succ.Push(c);
        return node.Value;
    }
}
```

## Likely follow-up questions

**Q: Why a window?**

If a value is among the k closest, every value between it and the target is closer, so it is in too.

**Q: Complexity?**

O(n) time and memory.

**Q: Faster?**

Two stacks — predecessors and successors of the target — then merge k steps: O(h + k).

**Q: Shared state?**

Read-only tree.

**Q: A huge BST and small k.**

The two-stack version never touches the rest of the tree.

**Q: Related?**

Find K Closest Elements (658) — the same window idea on an array, with binary search for the start.

